:siteUrl()+articlePath(a),image:siteUrl()+r.image,inLanguage:'ja',citation:a.sources.map(s=>s.url)})}}/><script type="application/ld+json" dangerouslySetInnerHTML={{__html:jsonLd({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'ホーム',item:siteUrl()},{'@type':'ListItem',position:2,name:r.name,item:siteUrl()+'/'+r.id},{'@type':'ListItem',position:3,name:a.title,item:siteUrl()+articlePath(a)}]})}}/></>}

