import Image from 'next/image';
import {notFound} from 'next/navigation';
import {photos} from '@/lib/photos';
import {PhotoCredit} from '@/components/photo-credit';
import {regions,getRegion,articles,jsonLd,siteUrl} from '@/lib/content';
import {ArticleCard,HotelCTA,Breadcrumb} from '@/components/ui';
export function generateStaticParams(){return regions.map(r=>({region:r.id}))}
export async function generateMetadata({params}:{params:Promise<{region:string}>}){const r=getRegion((await params).region);if(!r)return {};return {title:r.name+'で暮らすように旅する｜宿泊・交通・滞在ガイド',description:r.description,alternates:{canonical:'/'+r.id},openGraph:{title:r.name+'で暮らすように旅する',description:r.description,url:'/'+r.id,images:[{url:r.image}]}}}
const cityIntro={matsumoto:{copy:'山と街のあいだで、暮らすように旅する。',text:'城下町の道を歩き、いつもの店でひと休み。\n観光の合間に、買い物や散歩の時間を残してみる。\n街の日常に触れる、数日間の旅へ。',slugs:['everyday-3days','2nights-3days','stay-areas','car-or-no-car']},hakuba:{copy:'山のそばで、ゆっくり過ごす数日間。',text:'山を眺める時間も、旅のひとつ。\n予定を詰めすぎず、その日の天気に合わせて過ごす。\n自分のペースで、白馬に滞在してみる。',slugs:['everyday-hakuba','daytrip-from-matsumoto','stay-areas-hakuba']},itoigawa:{copy:'山から日本海へ、街の日常をたどる。',text:'石の成り立ちを知り、海のそばでひと休み。\n博物館や海岸を訪ねながら、街の距離を感じてみる。\n山と海をつなぐ、糸魚川の旅へ。',slugs:['one-day-geopark','everyday-itoigawa','three-cities-route']}};
export default async function RegionPage({params}:{params:Promise<{region:string}>}){const r=getRegion((await params).region);if(!r)notFound();const intro=cityIntro[r.id];return <>
<div className="section region-top"><Breadcrumb items={[{name:r.name}]}/><div className="region-lead"><div><h1>{r.name}</h1><p className="region-copy">{intro.copy}</p></div><figure className="region-photo"><Image src={r.image} alt={photos[r.id].alt} width={photos[r.id].width} height={photos[r.id].height} priority sizes="(max-width: 760px) 100vw, 50vw"/><figcaption><PhotoCredit region={r.id}/></figcaption></figure></div></div>
<section className="section city-about"><h2>この街について</h2><p>{intro.text}</p></section>
<section className="section city-reading"><div className="section-head"><h2>暮らすように旅する</h2></div><div className="cards">{intro.slugs.map(slug=>articles.find(a=>a.slug===slug)!).map(a=><ArticleCard key={a.slug} article={a}/>)}</div><HotelCTA region={r.id} article={'region-'+r.id} kind="region"/></section>
<script type="application/ld+json" dangerouslySetInnerHTML={{__html:jsonLd({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'ホーム',item:siteUrl()},{'@type':'ListItem',position:2,name:r.name,item:siteUrl()+'/'+r.id}]})}}/></>}

