import {Breadcrumb} from '@/components/ui';
import {photos} from '@/lib/photos';
import {PhotoCredit} from '@/components/photo-credit';
export const metadata={title:'運営・編集方針',alternates:{canonical:'/about'}};
export default function About(){return <div className="section narrow"><Breadcrumb items={[{name:'運営・編集方針'}]}/><p className="eyebrow">ABOUT THE JOURNAL</p><h1>旅と暮らしの、<br/>あいだを歩く。</h1><div className="prose"><p>旅暮らし情報局は、観光地を巡る旅に「その街で数日暮らしてみる」という視点を加えるWebメディアです。宿を選び、食事を買い、交通を使う。一つひとつの選択から、その街の日常を考えます。</p><h2>運営・執筆</h2><p>運営：旅暮らし情報局 / 編集・企画：たけ。公式情報に基づく調査記事は「旅暮らし情報局編集部」、本人の確認済み体験を主にする記事は「Editor / たけ」と表記します。現在のモデルコースは編集部による提案です。</p><h2>体験と調査を分けます</h2><p>訪問・利用を確認できた事実だけを旅の記録として掲載します。未確認の店・宿の利用や、AIによる疑似体験は書きません。季節や旅程の違う体験を、同じ日に起きた物語に組み替えません。</p><h2>情報の更新と出典</h2><p>記事には調査日と参照先を表示します。交通や料金は変わるため、予約・出発前に公式情報をご確認ください。予算や滞在配分は編集部の仮定として示します。情報の訂正はお問い合わせで受け付けます。</p><h2 id="photos">写真の出典・ライセンス</h2><p>掲載写真はWikimedia Commonsで利用条件を確認した地域の資料写真です。本人が撮影した旅の記録とは区別しています。撮影時期は現在の季節・状況と異なります。</p><ul className="photo-sources">{Object.entries(photos).map(([id,photo])=><li key={id}><strong>{photo.caption}</strong><PhotoCredit region={id as keyof typeof photos}/></li>)}</ul><p>掲載用に縮小された画像を使用し、画面に合わせてトリミング・圧縮しています。各写真の加工版にも記載の同一ライセンスを適用します。元写真、撮影者、利用条件は上記リンクから確認できます。</p><h2>広告と予約</h2><p>宿検索は外部サービスへ移動します。宿泊契約・決済・キャンセルは予約先の条件に従います。現在は非商用の試作で、広告・アフィリエイトによる収益は得ていません。将来収益化する場合は、利用サービスの契約条件と広告方針を見直してから開始します。</p></div></div>}

