import {NextResponse,after} from 'next/server';
import {randomUUID} from 'node:crypto';
import {contactConfigured,db,rateLimit,sendNotification,syncAttio} from '@/lib/services';
function fail(message:string,status:number){return NextResponse.json({message},{status})}
export async function POST(req:Request){if(!contactConfigured())return fail('現在、お問い合わせの受付準備中です。',503);if(req.headers.get('origin')!==new URL(process.env.SITE_URL||req.url).origin)return fail('送信元を確認できません。',403);if(!req.headers.get('content-type')?.includes('application/json'))return fail('形式が正しくありません。',415);const text=await req.text();if(text.length>8000)return fail('入力が長すぎます。',413);let x;try{x=JSON.parse(text)}catch{return fail('入力が正しくありません。',400)}if(x.website)return fail('送信内容を確認してください。',400);if(typeof x.name!=='string'||!x.name.trim()||x.name.length>80||typeof x.email!=='string'||x.email.length>254||!/^\S+@\S+\.\S+$/.test(x.email)||typeof x.message!=='string'||x.message.trim().length<10||x.message.length>3000||x.consent!==true||typeof x.startedAt!=='number'||Date.now()-x.startedAt<2000||Date.now()-x.startedAt>86400000)return fail('入力内容と同意をご確認ください。',400);try{if(!await rateLimit(req,'contact',5))return fail('送信が続いています。時間をおいてお試しください。',429);const id=randomUUID();await db('tk_inquiries',{id,name:x.name.trim(),email:x.email.trim(),message:x.message.trim(),consent_version:'2026-10-04',delivery_status:'pending'});after(async()=>{const [crm,mail]=await Promise.allSettled([syncAttio(id,x.name.trim(),x.email.trim()),sendNotification(id,x.email.trim())]);const status={attio:crm.status==='fulfilled'&&crm.value,admin:mail.status==='fulfilled'&&mail.value.admin,reply:mail.status==='fulfilled'&&mail.value.reply};try{await db(`tk_inquiries?id=eq.${id}`,{delivery_status:Object.values(status).every(Boolean)?'delivered':'needs_retry',integration_status:status},'PATCH')}catch{/* Do not log PII. Pending rows remain recoverable. */}});return NextResponse.json({id},{status:201})}catch{return fail('受付処理に失敗しました。入力内容を残したまま、時間をおいてお試しください。',503)}}

