import {NextResponse,after} from 'next/server';
import {getRegion} from '@/lib/content';
import {provider} from '@/lib/affiliate';
import {dbConfigured,recordClick,rateLimit} from '@/lib/services';
export async function GET(req:Request,{params}:{params:Promise<{region:string}>}){const r=getRegion((await params).region);if(!r)return new NextResponse('Not found',{status:404});const p=provider(),u=new URL(req.url),destination=p.buildUrl(r.id);const data={region:r.id,article:(u.searchParams.get('article')||'unknown').slice(0,100),cta_kind:(u.searchParams.get('kind')||'article').slice(0,32),provider:p.id,destination};if(dbConfigured()&&req.headers.get('purpose')!=='prefetch'&&!req.headers.get('sec-purpose')?.includes('prefetch'))after(async()=>{try{if(await rateLimit(req,'click',120))await recordClick(data)}catch{/* Navigation must work even if analytics is unavailable. */}});const res=NextResponse.redirect(destination,302);res.headers.set('Cache-Control','no-store');res.headers.set('X-Robots-Tag','noindex');return res}

