'use client';
import {useState,useRef} from 'react';
export default function ContactForm({enabled}:{enabled:boolean}){const [status,setStatus]=useState(''),[busy,setBusy]=useState(false);const started=useRef(Date.now());async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);const form=e.currentTarget;const values=Object.fromEntries(new FormData(form));try{const r=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,consent:values.consent==='on',startedAt:started.current})});const data=await r.json();if(r.ok){setStatus('お問い合わせを受け付けました。受付番号：'+data.id);form.reset();started.current=Date.now()}else setStatus(data.message||'送信できませんでした。時間をおいてお試しください。')}catch{setStatus('通信できませんでした。入力内容は残っています。')}finally{setBusy(false)}}return <form className="contact-form" onSubmit={submit}><label>お名前<input name="name" maxLength={80} autoComplete="name" required/></label><label>メールアドレス<input name="email" type="email" maxLength={254} autoComplete="email" required/></label><label>お問い合わせ内容<textarea name="message" minLength={10} maxLength={3000} rows={7} required/></label><div className="honeypot" aria-hidden="true"><label>Website<input name="website" tabIndex={-1} autoComplete="off"/></label></div><label className="check"><input name="consent" type="checkbox" required/><span><a href="/privacy">プライバシーポリシー</a>を確認し、対応に必要な情報の利用に同意します。</span></label>{!enabled&&<p className="notice">お問い合わせの受付準備中です。受付開始後、このフォームから送信できます。</p>}<button className="button" disabled={!enabled||busy}>{busy?'送信中…':'お問い合わせを送る'}</button><p aria-live="polite" role="status">{status}</p></form>}

