'use client';
import {useState} from 'react';
import {Search,ArrowRight} from 'lucide-react';
import {articles,styles,regions} from '@/lib/content';
import {ArticleCard} from './article-card';
export default function SearchArticles(){const [q,setQ]=useState(''),[region,setRegion]=useState(''),[style,setStyle]=useState('');const filtered=articles.filter(a=>(!region||a.region===region)&&(!style||a.tags.includes(style))&&(!q||[a.title,a.description,...a.tags,regions.find(r=>r.id===a.region)?.name].join(' ').toLowerCase().includes(q.toLowerCase())));return <><div className="search-panel"><label className="search-field"><Search size={20}/><input aria-label="記事を検索" placeholder="街の名前、車なし、ワーケーション…" value={q} onChange={e=>setQ(e.target.value)}/></label><label>地域<select value={region} onChange={e=>setRegion(e.target.value)}><option value="">すべての地域</option>{regions.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label>旅のスタイル<select value={style} onChange={e=>setStyle(e.target.value)}><option value="">すべてのスタイル</option>{styles.map(s=><option key={s}>{s}</option>)}</select></label></div><p className="result-count">{filtered.length}件の旅の読みもの</p><div className="cards">{filtered.map(a=><ArticleCard key={a.slug} article={a}/>)}</div>{!filtered.length&&<div className="empty">条件に合う記事がありません。<button onClick={()=>{setQ('');setStyle('');setRegion('')}}>条件をリセット <ArrowRight size={14}/></button></div>}</>}

