import {getRegion, type RegionId} from './content';
export interface AffiliateProvider {id:string; buildUrl(region:RegionId):string; monetized:boolean;}
export function provider():AffiliateProvider {return {id:'booking',monetized:process.env.AFFILIATE_ENABLED==='true'&&Boolean(process.env.BOOKING_AFFILIATE_ID),buildUrl(region){const u=new URL('https://www.booking.com/searchresults.ja.html');u.searchParams.set('ss',getRegion(region)!.name+' 日本');if(process.env.AFFILIATE_ENABLED==='true'&&process.env.BOOKING_AFFILIATE_ID)u.searchParams.set('aid',process.env.BOOKING_AFFILIATE_ID);return u.toString()}}}
export function affiliatePath(region:RegionId,article:string,kind='article'){return `/go/${region}?article=${encodeURIComponent(article)}&kind=${encodeURIComponent(kind)}`}

