{id:'matsumoto',name:'松本',en:'MATSUMOTO',kicker:'城下町で、日常に寄り道。',description:'城と工芸の街を歩き、ときどき自転車に乗る。観光の隣にある、いつもの暮らしを探す旅。',days:'2泊3日〜1週間',mobility:'中心部は車なしでも',image:'/images/matsumoto.jpg',tags:['3日暮らす','1週間滞在','車なし','ローカルな街','温泉','移住前のお試し滞在'],migration:'https://www.city.matsumoto.nagano.jp/site/matsumotogurashi/'},
{id:'hakuba',name:'白馬',en:'HAKUBA',kicker:'山を眺める時間も、旅になる。',description:'予定を詰めすぎず、山の天気に合わせて過ごす。泊まる場所と生活の動線から、白馬を考える。',days:'2泊〜1週間',mobility:'宿の送迎・車を確認',image:'/images/hakuba.jpg',tags:['3日暮らす','1週間滞在','自然の近く','温泉','ワーケーション','移住前のお試し滞在'],migration:'https://www.vill.hakuba.lg.jp/gyosei/soshikikarasagasu/somuka/kikakuchoseigakari/2/1427.html'},
{id:'itoigawa',name:'糸魚川',en:'ITOIGAWA',kicker:'石を知ると、海の見え方が変わる。',description:'フォッサマグナを学び、日本海のそばでひと休み。駅前と郊外を分けて、無理なく滞在する。',days:'日帰り〜3泊',mobility:'郊外を巡るなら車が便利',image:'/images/itoigawa.jpg',tags:['3日暮らす','自然の近く','ローカルな街','移住前のお試し滞在'],migration:'https://www.city.itoigawa.lg.jp/site/ijyuu/index-2.html'}];
export const styles=['3日暮らす','1週間滞在','車なし','自然の近く','温泉','ワーケーション','ローカルな街','移住前のお試し滞在'];
export function getRegion(id:string){return regions.find(r=>r.id===id)}
export function getArticle(region:string,slug:string){return articles.find(a=>a.region===region&&a.slug===slug)}
export function articlePath(a:Article){return `/${a.region}/${a.slug}`}
export function siteUrl(){return process.env.SITE_URL||'http://localhost:3000'}
export function jsonLd(data:unknown){return JSON.stringify(data).replace(/</g,'\\u003c')}

