import 'server-only';
import {createHmac} from 'node:crypto';
export function dbConfigured(){return Boolean(process.env.SUPABASE_URL&&process.env.SUPABASE_SERVICE_ROLE_KEY&&process.env.RATE_LIMIT_SECRET)}
export function contactConfigured(){return dbConfigured()&&(process.env.CONTACT_REQUIRE_ALL==='false'||Boolean(process.env.ATTIO_API_KEY&&process.env.RESEND_API_KEY&&process.env.RESEND_FROM&&process.env.CONTACT_ADMIN_EMAIL))}
async function api(url:string,init:RequestInit){const res=await fetch(url,{...init,signal:AbortSignal.timeout(8000),cache:'no-store'});if(!res.ok)throw new Error('external_service_error');return res.status===204?null:res.json()}
export async function db(path:string,body:unknown,method='POST'){return api(`${process.env.SUPABASE_URL}/rest/v1/${path}`,{method,headers:{apikey:process.env.SUPABASE_SERVICE_ROLE_KEY!,Authorization:`Bearer ${process.env.SUPABASE_SERVICE_ROLE_KEY!}`,'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(body)})}
export async function rateLimit(req:Request,namespace:string,limit:number){const address=req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()||'unknown';const day=new Date().toISOString().slice(0,10);const key=createHmac('sha256',process.env.RATE_LIMIT_SECRET!).update(namespace+day+address).digest('hex');return db('rpc/tk_take_rate_slot',{p_key:key,p_limit:limit})}
export async function sendNotification(id:string,email:string){const key=process.env.RESEND_API_KEY;if(!key||!process.env.RESEND_FROM||!process.env.CONTACT_ADMIN_EMAIL)return {admin:false,reply:false};async function send(to:string,subject:string,text:string,kind:string){await api(`${process.env.RESEND_API_BASE||'https://api.resend.com'}/emails`,{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json','Idempotency-Key':`tk-${id}-${kind}`},body:JSON.stringify({from:process.env.RESEND_FROM,to:[to],subject,text})})}const results=await Promise.allSettled([send(process.env.CONTACT_ADMIN_EMAIL,'旅暮らし情報局：お問い合わせ受付',`お問い合わせを受け付けました。受付番号：${id}。内容はSupabaseの管理画面から確認してください。`,'admin'),send(email,'旅暮らし情報局：お問い合わせを受け付けました',`お問い合わせありがとうございます。受付番号：${id}\n内容を確認し、順次対応します。このメールにはお問い合わせ本文を掲載していません。`,'reply')]);return {admin:results[0].status==='fulfilled',reply:results[1].status==='fulfilled'}}
export async function syncAttio(id:string,name:string,email:string){if(!process.env.ATTIO_API_KEY)return false;await api(`${process.env.ATTIO_API_BASE||'https://api.attio.com'}/v2/objects/people/records?matching_attribute=email_addresses`,{method:'PUT',headers:{Authorization:`Bearer ${process.env.ATTIO_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({data:{values:{email_addresses:[{email_address:email}]}}})});return true}
export async function recordClick(data:{article:string;region:string;cta_kind:string;provider:string;destination:string}){await db('tk_cta_events',data)}

