supabase/schema.sql.text:
-- Execute on a dedicated project. No existing tables are changed.
create table public.tk_inquiries (
 id uuid primary key,
 name text not null check(char_length(name) between 1 and 80),
 email text not null check(char_length(email) <= 254),
 message text not null check(char_length(message) between 10 and 3000),
 consent_version text not null,
 created_at timestamptz not null default now(),
 delivery_status text not null default 'pending' check(delivery_status in ('pending','delivered','needs_retry')),
 integration_status jsonb not null default '{}'
);
create table public.tk_cta_events (
 id uuid primary key default gen_random_uuid(),
 article text not null check(char_length(article)<=100),
 region text not null check(region in ('matsumoto','hakuba','itoigawa')),
 cta_kind text not null check(char_length(cta_kind)<=32),
 provider text not null,
 destination text not null,
 created_at timestamptz not null default now()
);
create table public.tk_rate_limits (
 key text primary key,
 attempts integer not null default 1,
 expires_at timestamptz not null default now()+interval '24 hours'
);
alter table public.tk_inquiries enable row level security;
alter table public.tk_cta_events enable row level security;
alter table public.tk_rate_limits enable row level security;
revoke all on public.tk_inquiries,public.tk_cta_events,public.tk_rate_limits from anon,authenticated;
grant all on public.tk_inquiries,public.tk_cta_events,public.tk_rate_limits to service_role;
create index tk_cta_events_region_created on public.tk_cta_events(region,created_at);
create index tk_inquiries_delivery on public.tk_inquiries(delivery_status,created_at);
create or replace function public.tk_take_rate_slot(p_key text,p_limit integer) returns boolean
language plpgsql security invoker set search_path='' as $$
declare n integer;
begin
 delete from public.tk_rate_limits where expires_at<now();
 insert into public.tk_rate_limits(key) values(p_key)
 on conflict(key) do update set attempts=public.tk_rate_limits.attempts+1
 returning attempts into n;
 return n<=p_limit;
end;
$$;
revoke execute on function public.tk_take_rate_slot(text,integer) from public,anon,authenticated;
grant execute on function public.tk_take_rate_slot(text,integer) to service_role;

