import http from 'node:http';
const state={inquiries:[],events:[],attio:[],mail:[],limits:{},failMail:false};
http.createServer(async(req,res)=>{let text='';for await(const c of req)text+=c;let x;try{x=text?JSON.parse(text):null}catch{};const url=new URL(req.url,'http://localhost');res.setHeader('Content-Type','application/json');function done(x,status=200){res.statusCode=status;res.end(JSON.stringify(x))}
if(url.pathname==='/test/state')return done(state);
if(url.pathname==='/test/reset'){state.inquiries=[];state.events=[];state.attio=[];state.mail=[];state.limits={};state.failMail=Boolean(x?.failMail);return done({ok:true})}
if(url.pathname==='/rest/v1/rpc/tk_take_rate_slot'){const n=state.limits[x.p_key]=(state.limits[x.p_key]||0)+1;return done(n<=x.p_limit)}
if(url.pathname==='/rest/v1/tk_inquiries'){if(req.method==='POST'){state.inquiries.push(x);return done([x],201)}if(req.method==='PATCH'){const id=url.searchParams.get('id')?.slice(3),row=state.inquiries.find(v=>v.id===id);Object.assign(row||{},x);return done(row?[row]:[])}return done(state.inquiries)}
if(url.pathname==='/rest/v1/tk_cta_events'){state.events.push({...x,created_at:new Date().toISOString()});return done([x],201)}
if(url.pathname==='/v2/objects/people/records'){state.attio.push(x);return done({data:{id:{record_id:'test-record'}}})}
if(url.pathname==='/emails'){state.mail.push(x);return state.failMail?done({error:'unavailable'},503):done({id:'test-email'})}
return done({error:'not found'},404)
}).listen(4010,'127.0.0.1',()=>console.log('Isolated service contract mocks on 4010'));

