import {test,expect} from '@playwright/test';
import fs from 'node:fs';
const articles=JSON.parse(fs.readFileSync('content/catalog.json','utf8')) as {region:string;slug:string;featured:boolean}[];
const regions=['matsumoto','hakuba','itoigawa'].map(id=>({id}));
const styles=['3日暮らす','1週間滞在','車なし','自然の近く','温泉','ワーケーション','ローカルな街','移住前のお試し滞在'];
const articlePath=(a:{region:string;slug:string})=>`/${a.region}/${a.slug}`;
const paths=['/',...regions.map(r=>'/'+r.id),...articles.map(articlePath),'/articles','/about','/privacy','/contact',...styles.map(s=>'/styles/'+encodeURIComponent(s))];
for(const path of paths)test(`Page and SEO: ${path}`,async({page})=>{const errors:string[]=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});const r=await page.goto(path);expect(r?.status()).toBe(200);await expect(page.locator('h1')).toHaveCount(1);await expect(page.locator('link[rel="canonical"]')).toHaveCount(1);expect(await page.title()).toContain('旅暮らし情報局');expect(errors).toEqual([]);for(const text of await page.locator('script[type="application/ld+json"]').allTextContents())expect(JSON.parse(text)['@type']).toBeTruthy()});
test('mobile screens, no horizontal overflow and menu',async({page})=>{await page.setViewportSize({width:390,height:844});for(const path of ['/',...regions.map(r=>'/'+r.id),...articles.filter(a=>a.featured).map(articlePath),'/contact']){await page.goto(path);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth)).toBe(true)}await page.goto('/');await page.evaluate(()=>document.fonts.ready);await page.screenshot({path:'docs/mobile-home.png',fullPage:true});await page.getByRole('link',{name:'記事',exact:true}).click();await expect(page).toHaveURL(/articles/)});
test('search, filter, reset',async({page})=>{await page.goto('/articles');await page.getByRole('textbox',{name:'記事を検索'}).fill('松本');expect(await page.locator('.article-card').count()).toBeGreaterThan(0);await page.getByRole('textbox',{name:'記事を検索'}).fill('no-result-123');await expect(page.locator('.article-card')).toHaveCount(0);await page.getByRole('button',{name:/条件をリセット/}).click();await expect(page.locator('.article-card')).toHaveCount(10)});
test('internal links and CTA destinations',async({page,request})=>{const links=new Set<string>();for(const path of paths){await page.goto(path);for(const href of await page.locator('a[href^="/"]').evaluateAll(nodes=>nodes.map(n=>n.getAttribute('href')!)))links.add(href)}for(const href of links){const r=await request.get(href,{maxRedirects:0});if(href.startsWith('/go/')){expect(r.status()).toBe(302);expect(new URL(r.headers().location).hostname).toBe('www.booking.com')}else expect(r.status(),href).toBe(200)}});
test('404 is genuine',async({page})=>{const r=await page.goto('/this-region-does-not-exist');expect(r?.status()).toBe(404);await expect(page.getByRole('heading',{name:'道を、少し外れたようです。'})).toBeVisible()});
test('sitemap and robots',async({request})=>{const r=await request.get('/sitemap.xml');expect(r.status()).toBe(200);const xml=await r.text();expect((xml.match(/<url>/g)||[]).length).toBe(26);expect(xml).toContain('/matsumoto/2nights-3days');const robots=await request.get('/robots.txt');expect(await robots.text()).toContain('Disallow: /api/');expect(await robots.text()).toContain('Sitemap: http://localhost:3000/sitemap.xml')});
test('form pipeline contracts, minimum CRM data, two isolated emails',async({page,request})=>{await request.post('http://localhost:4010/test/reset',{data:{}});await page.goto('/contact');await page.getByLabel('お名前',{exact:true}).fill('MVPテスト');await page.getByLabel('メールアドレス',{exact:true}).fill('test@example.test');await page.getByLabel('お問い合わせ内容',{exact:true}).fill('問い合わせパイプライン検証用の架空データです。');await page.getByRole('checkbox').check();await page.waitForTimeout(2100);await page.getByRole('button',{name:'お問い合わせを送る'}).click();await expect(page.getByRole('status')).toContainText('お問い合わせを受け付けました');await expect.poll(async()=>{const s=await (await request.get('http://localhost:4010/test/state')).json();return s.inquiries[0]?.delivery_status}).toBe('delivered');const s=await(await request.get('http://localhost:4010/test/state')).json();expect(s.inquiries).toHaveLength(1);expect(s.attio).toHaveLength(1);expect(s.mail).toHaveLength(2);expect(JSON.stringify(s.attio)).not.toContain('問い合わせパイプライン');expect(s.mail[0].text).not.toContain('問い合わせパイプライン')});
test('form rejects cross-origin, invalid data, honeypot and floods',async({request})=>{await request.post('http://localhost:4010/test/reset',{data:{}});const data={name:'Test',email:'test@example.test',message:'テストお問い合わせ内容です。',consent:true,startedAt:Date.now()-3000};const cross=await request.post('/api/contact',{headers:{Origin:'https://untrusted.example'},data});expect(cross.status()).toBe(403);const invalid=await request.post('/api/contact',{headers:{Origin:'http://localhost:3000'},data:{...data,email:'bad'}});expect(invalid.status()).toBe(400);const bot=await request.post('/api/contact',{headers:{Origin:'http://localhost:3000'},data:{...data,website:'spam'}});expect(bot.status()).toBe(400);for(let i=0;i<5;i++)expect((await request.post('/api/contact',{headers:{Origin:'http://localhost:3000'},data})).status()).toBe(201);expect((await request.post('/api/contact',{headers:{Origin:'http://localhost:3000'},data})).status()).toBe(429)});
test('outbox marks failed mail for recovery',async({request})=>{await request.post('http://localhost:4010/test/reset',{data:{failMail:true}});const r=await request.post('/api/contact',{headers:{Origin:'http://localhost:3000'},data:{name:'Test',email:'test@example.test',message:'連携失敗の状態管理テストです。',consent:true,startedAt:Date.now()-3000}});expect(r.status()).toBe(201);await expect.poll(async()=>{const s=await(await request.get('http://localhost:4010/test/state')).json();return s.inquiries[0]?.delivery_status}).toBe('needs_retry')});
test('CTA records provenance and never accepts an arbitrary destination',async({request})=>{await request.post('http://localhost:4010/test/reset',{data:{}});const r=await request.get('/go/hakuba?article=everyday-hakuba&kind=article&url=https://untrusted.example',{maxRedirects:0});expect(new URL(r.headers().location).hostname).toBe('www.booking.com');await expect.poll(async()=>{const s=await(await request.get('http://localhost:4010/test/state')).json();return s.events.length}).toBe(1);const s=await(await request.get('http://localhost:4010/test/state')).json();expect(s.events[0].region).toBe('hakuba');expect(s.events[0].article).toBe('everyday-hakuba');expect(s.events[0].created_at).toBeTruthy()});
test('desktop screenshot',async({page})=>{await page.setViewportSize({width:1440,height:1000});await page.goto('/');await page.evaluate(()=>document.fonts.ready);await page.screenshot({path:'docs/desktop-home.png',fullPage:true})});

