components/photo-credit.tsx.text:
import {photos} from '@/lib/photos';
import type {RegionId} from '@/lib/content';

export function PhotoCredit({region}: {region: RegionId}) {
  const photo = photos[region];
  return <span className="photo-credit">Photo: <a href={photo.source} target="_blank" rel="noopener noreferrer">{photo.author}</a> / <a href={photo.licenseUrl} target="_blank" rel="noopener noreferrer">{photo.license}</a><span className="photo-date">撮影：{photo.date}</span></span>;
}
